/* =====================================================================
   Migracion_04_Validacion.sql  -  SOLO CONSULTAS (no modifica nada)

   Base: dbcordatv485Cor (prod).
   Cuando ejecutarlo: DESPUES de Migracion_02_Datos.sql (con COMMIT) y ANTES de Migracion_03_Cierre.sql.
   Si ya se renombraron las originales (Migracion_03), reemplazar en este script dbo.INCIDENTES por dbo.INCIDENTES_OLD, etc.

   COMO LEERLO
     A) RESUMEN: cada fila es un control y debe dar 0 filas con problema (RESULTADO = OK). Las que digan REVISAR se investigan
        con el detalle del bloque B. REVISAR no siempre es un error: por ejemplo, un responsable que ya no esta en AD queda
        sin login en vw_UserGrupos; es un dato historico a decidir.
     B) DETALLE: listados para entender cada REVISAR.
   ===================================================================== */

USE [dbcordatv485Cor]
GO

-- =====================================================================
-- A) RESUMEN DE CONTROLES (esperado: 0 filas con problema)
-- =====================================================================
SELECT x.CONTROL, x.FILAS_CON_PROBLEMA, CASE WHEN x.FILAS_CON_PROBLEMA = 0 THEN 'OK' ELSE 'REVISAR' END AS RESULTADO
FROM (
    -- A1) Conteos: diferencia entre la tabla original y la CG_ (debe ser 0)
    SELECT 'Conteo AGENDA' AS CONTROL, ABS((SELECT COUNT(*) FROM dbo.AGENDA) - (SELECT COUNT(*) FROM dbo.CG_AGENDA)) AS FILAS_CON_PROBLEMA
    UNION ALL SELECT 'Conteo APL', ABS((SELECT COUNT(*) FROM dbo.APL) - (SELECT COUNT(*) FROM dbo.CG_APL))
    UNION ALL SELECT 'Conteo APL_RELAC', ABS((SELECT COUNT(*) FROM dbo.APL_RELAC) - (SELECT COUNT(*) FROM dbo.CG_APL_RELAC))
    UNION ALL SELECT 'Conteo APLICATIVOS', ABS((SELECT COUNT(*) FROM dbo.APLICATIVOS) - (SELECT COUNT(*) FROM dbo.CG_APLICATIVOS))
    UNION ALL SELECT 'Conteo BROWSERS', ABS((SELECT COUNT(*) FROM dbo.BROWSERS) - (SELECT COUNT(*) FROM dbo.CG_BROWSERS))
    UNION ALL SELECT 'Conteo CLIEN_X_APLIC', ABS((SELECT COUNT(*) FROM dbo.CLIEN_X_APLIC) - (SELECT COUNT(*) FROM dbo.CG_CLIEN_X_APLIC))
    UNION ALL SELECT 'Conteo CLIENTES', ABS((SELECT COUNT(*) FROM dbo.CLIENTES) - (SELECT COUNT(*) FROM dbo.CG_CLIENTES))
    UNION ALL SELECT 'Conteo CLIENTES_DET', ABS((SELECT COUNT(*) FROM dbo.CLIENTES_DET) - (SELECT COUNT(*) FROM dbo.CG_CLIENTES_DET))
    UNION ALL SELECT 'Conteo CONTACTOS', ABS((SELECT COUNT(*) FROM dbo.CONTACTOS) - (SELECT COUNT(*) FROM dbo.CG_CONTACTOS))
    UNION ALL SELECT 'Conteo ESTADISTICAS', ABS((SELECT COUNT(*) FROM dbo.ESTADISTICAS) - (SELECT COUNT(*) FROM dbo.CG_ESTADISTICAS))
    UNION ALL SELECT 'Conteo INCIDENTES', ABS((SELECT COUNT(*) FROM dbo.INCIDENTES) - (SELECT COUNT(*) FROM dbo.CG_INCIDENTES))
    UNION ALL SELECT 'Conteo LICENCIAS', ABS((SELECT COUNT(*) FROM dbo.LICENCIAS) - (SELECT COUNT(*) FROM dbo.CG_LICENCIAS))
    UNION ALL SELECT 'Conteo PRIORIDADES', ABS((SELECT COUNT(*) FROM dbo.PRIORIDADES) - (SELECT COUNT(*) FROM dbo.CG_PRIORIDADES))
    UNION ALL SELECT 'Conteo PROYECTOS', ABS((SELECT COUNT(*) FROM dbo.PROYECTOS) - (SELECT COUNT(*) FROM dbo.CG_PROYECTOS))
    UNION ALL SELECT 'Conteo RELAINC -> CG_AVANCES', ABS((SELECT COUNT(*) FROM dbo.RELAINC) - (SELECT COUNT(*) FROM dbo.CG_AVANCES))
    UNION ALL SELECT 'Conteo VIA_PEDIDO', ABS((SELECT COUNT(*) FROM dbo.VIA_PEDIDO) - (SELECT COUNT(*) FROM dbo.CG_VIA_PEDIDO))
    UNION ALL SELECT 'Conteo tipo_apl', ABS((SELECT COUNT(*) FROM dbo.tipo_apl) - (SELECT COUNT(*) FROM dbo.CG_TIPO_APL))

    -- A2) Referencias de CG_INCIDENTES (cada una debe existir en su tabla padre)
    UNION ALL SELECT 'INCIDENTES: cliente inexistente', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE i.ID_CLIENTE IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_CLIENTES c WHERE c.ID = i.ID_CLIENTE)
    UNION ALL SELECT 'INCIDENTES: aplicativo inexistente', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE i.ID_APLIC IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_APLICATIVOS a WHERE a.ID = i.ID_APLIC)
    UNION ALL SELECT 'INCIDENTES: contacto inexistente', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE ISNULL(i.CONTACTO, 0) <> 0 AND NOT EXISTS (SELECT 1 FROM dbo.CG_CONTACTOS c WHERE c.ID = i.CONTACTO)
    UNION ALL SELECT 'INCIDENTES: prioridad inexistente', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE i.PRIORIDAD IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_PRIORIDADES p WHERE p.ID = i.PRIORIDAD)
    UNION ALL SELECT 'INCIDENTES: browser inexistente', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE i.BROWSER IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_BROWSERS b WHERE b.ID = i.BROWSER)
    UNION ALL SELECT 'INCIDENTES: via de pedido inexistente', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE i.VIA_PEDIDO IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_VIA_PEDIDO v WHERE v.ID = i.VIA_PEDIDO)
    UNION ALL SELECT 'INCIDENTES: proyecto inexistente', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE ISNULL(i.ID_PROYECTO, 0) <> 0 AND NOT EXISTS (SELECT 1 FROM dbo.CG_PROYECTOS p WHERE p.ID = i.ID_PROYECTO)
    UNION ALL SELECT 'INCIDENTES: estado desarrollo/funcional inexistente', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE (ISNULL(i.ESTADO_DESA, 0) <> 0 AND NOT EXISTS (SELECT 1 FROM dbo.CG_ESTADOS e WHERE e.ID = i.ESTADO_DESA)) OR (ISNULL(i.ESTADO_FUNC, 0) <> 0 AND NOT EXISTS (SELECT 1 FROM dbo.CG_ESTADOS e WHERE e.ID = i.ESTADO_FUNC))
    UNION ALL SELECT 'INCIDENTES: APL inexistente', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE ISNULL(i.ID_APL, 0) <> 0 AND NOT EXISTS (SELECT 1 FROM dbo.CG_APL a WHERE a.ID = i.ID_APL)

    -- A3) Referencias de CG_PROYECTOS
    UNION ALL SELECT 'PROYECTOS: cliente inexistente', COUNT(*) FROM dbo.CG_PROYECTOS p WHERE p.ID_CLIENTE IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_CLIENTES c WHERE c.ID = p.ID_CLIENTE)
    UNION ALL SELECT 'PROYECTOS: aplicativo inexistente', COUNT(*) FROM dbo.CG_PROYECTOS p WHERE p.ID_APLIC IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_APLICATIVOS a WHERE a.ID = p.ID_APLIC)
    UNION ALL SELECT 'PROYECTOS: contacto inexistente', COUNT(*) FROM dbo.CG_PROYECTOS p WHERE ISNULL(p.CONTACTO, 0) <> 0 AND NOT EXISTS (SELECT 1 FROM dbo.CG_CONTACTOS c WHERE c.ID = p.CONTACTO)
    UNION ALL SELECT 'PROYECTOS: prioridad inexistente', COUNT(*) FROM dbo.CG_PROYECTOS p WHERE p.PRIORIDAD IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_PRIORIDADES x WHERE x.ID = p.PRIORIDAD)
    UNION ALL SELECT 'PROYECTOS: browser o via de pedido inexistente', COUNT(*) FROM dbo.CG_PROYECTOS p WHERE (p.BROWSER IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_BROWSERS b WHERE b.ID = p.BROWSER)) OR (p.VIA_PEDIDO IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_VIA_PEDIDO v WHERE v.ID = p.VIA_PEDIDO))

    -- A4) Avances, APL y relaciones
    UNION ALL SELECT 'AVANCES: incidente inexistente', COUNT(*) FROM dbo.CG_AVANCES a WHERE a.TIPOOBJETO = 'inc' AND NOT EXISTS (SELECT 1 FROM dbo.CG_INCIDENTES i WHERE i.ID = a.CODOBJETO)
    UNION ALL SELECT 'AVANCES: proyecto inexistente', COUNT(*) FROM dbo.CG_AVANCES a WHERE a.TIPOOBJETO = 'proy' AND NOT EXISTS (SELECT 1 FROM dbo.CG_PROYECTOS p WHERE p.ID = a.CODOBJETO)
    UNION ALL SELECT 'AVANCES: tipo de objeto distinto de inc / proy', COUNT(*) FROM dbo.CG_AVANCES a WHERE ISNULL(a.TIPOOBJETO, '') NOT IN ('inc', 'proy')
    UNION ALL SELECT 'AVANCES: estado inexistente', COUNT(*) FROM dbo.CG_AVANCES a WHERE ISNULL(a.IDESTADO, 0) <> 0 AND NOT EXISTS (SELECT 1 FROM dbo.CG_ESTADOS e WHERE e.ID = a.IDESTADO)
    UNION ALL SELECT 'APL: cliente o aplicativo inexistente', COUNT(*) FROM dbo.CG_APL a WHERE (a.ID_CLIENTE IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_CLIENTES c WHERE c.ID = a.ID_CLIENTE)) OR (a.ID_APLIC IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_APLICATIVOS x WHERE x.ID = a.ID_APLIC))
    UNION ALL SELECT 'APL_RELAC: APL inexistente', COUNT(*) FROM dbo.CG_APL_RELAC r WHERE NOT EXISTS (SELECT 1 FROM dbo.CG_APL a WHERE a.ID = r.ID_APL)
    UNION ALL SELECT 'CONTACTOS: cliente inexistente', COUNT(*) FROM dbo.CG_CONTACTOS c WHERE c.ID_CLIENTE IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_CLIENTES x WHERE x.ID = c.ID_CLIENTE)
    UNION ALL SELECT 'CLIEN_X_APLIC: cliente o aplicativo inexistente', COUNT(*) FROM dbo.CG_CLIEN_X_APLIC c WHERE (c.ID_CLIENTE IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_CLIENTES x WHERE x.ID = c.ID_CLIENTE)) OR (c.ID_APLIC IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_APLICATIVOS a WHERE a.ID = c.ID_APLIC))
    UNION ALL SELECT 'CLIENTES_DET: cliente inexistente', COUNT(*) FROM dbo.CG_CLIENTES_DET d WHERE d.ID_CLIENTE IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.CG_CLIENTES x WHERE x.ID = d.ID_CLIENTE)

    -- A5) Responsables: id de origen que no obtuvo login (*_SEG)
    UNION ALL SELECT 'INCIDENTES: responsable de gestion sin login', COUNT(*) FROM dbo.CG_INCIDENTES WHERE RESPON_GESTION IS NOT NULL AND RESPON_GESTION_SEG IS NULL
    UNION ALL SELECT 'INCIDENTES: responsable tecnico sin login', COUNT(*) FROM dbo.CG_INCIDENTES WHERE ISNULL(RESPON_TEC, 0) <> 0 AND RESPON_TEC_SEG IS NULL
    UNION ALL SELECT 'PROYECTOS: responsable de gestion sin login', COUNT(*) FROM dbo.CG_PROYECTOS WHERE RESPON_GESTION IS NOT NULL AND RESPON_GESTION_SEG IS NULL
    UNION ALL SELECT 'PROYECTOS: responsable tecnico sin login', COUNT(*) FROM dbo.CG_PROYECTOS WHERE ISNULL(RESPON_TEC, 0) <> 0 AND RESPON_TEC_SEG IS NULL
    UNION ALL SELECT 'AGENDA: responsable sin login', COUNT(*) FROM dbo.CG_AGENDA WHERE ID_RESPON IS NOT NULL AND ID_RESPON_SEG IS NULL
    UNION ALL SELECT 'LICENCIAS: responsable sin login', COUNT(*) FROM dbo.CG_LICENCIAS WHERE ID_RESPON IS NOT NULL AND ID_RESPON_SEG IS NULL
    UNION ALL SELECT 'APL: responsable de envio sin login', COUNT(*) FROM dbo.CG_APL WHERE ISNULL(RESPON_ENVIO, 0) <> 0 AND RESPON_ENVIO_SEG IS NULL
    UNION ALL SELECT 'AVANCES: usuario sin login', COUNT(*) FROM dbo.CG_AVANCES WHERE IDUSUARIO_SEG IS NULL

    -- A6) Responsables: login que no existe hoy en vw_UserGrupos (personas dadas de baja en AD; dato historico a decidir)
    UNION ALL SELECT 'INCIDENTES: login de gestion/tecnico fuera de vw_UserGrupos', COUNT(*) FROM dbo.CG_INCIDENTES i WHERE (i.RESPON_GESTION_SEG IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.vw_UserGrupos u WHERE u.USRNET = i.RESPON_GESTION_SEG)) OR (i.RESPON_TEC_SEG IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.vw_UserGrupos u WHERE u.USRNET = i.RESPON_TEC_SEG))
    UNION ALL SELECT 'PROYECTOS: login de gestion/tecnico fuera de vw_UserGrupos', COUNT(*) FROM dbo.CG_PROYECTOS p WHERE (p.RESPON_GESTION_SEG IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.vw_UserGrupos u WHERE u.USRNET = p.RESPON_GESTION_SEG)) OR (p.RESPON_TEC_SEG IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.vw_UserGrupos u WHERE u.USRNET = p.RESPON_TEC_SEG))
    UNION ALL SELECT 'AGENDA: login fuera de vw_UserGrupos', COUNT(*) FROM dbo.CG_AGENDA a WHERE a.ID_RESPON_SEG IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.vw_UserGrupos u WHERE u.USRNET = a.ID_RESPON_SEG)
    UNION ALL SELECT 'LICENCIAS: login fuera de vw_UserGrupos', COUNT(*) FROM dbo.CG_LICENCIAS l WHERE l.ID_RESPON_SEG IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.vw_UserGrupos u WHERE u.USRNET = l.ID_RESPON_SEG)

    -- A7) Contenido: el dato migrado debe coincidir con el original (por ID)
    UNION ALL SELECT 'INCIDENTES: DETALLES distinto del original', COUNT(*) FROM dbo.INCIDENTES o INNER JOIN dbo.CG_INCIDENTES c ON c.ID = o.ID WHERE ISNULL(CAST(o.DETALLES AS NVARCHAR(MAX)), N'') <> ISNULL(CAST(c.DETALLES AS NVARCHAR(MAX)), N'')
    UNION ALL SELECT 'INCIDENTES: AVANCES distinto del original (largo)', COUNT(*) FROM dbo.INCIDENTES o INNER JOIN dbo.CG_INCIDENTES c ON c.ID = o.ID WHERE ISNULL(LEN(CAST(o.AVANCES AS NVARCHAR(MAX))), 0) <> ISNULL(LEN(CAST(c.AVANCES AS NVARCHAR(MAX))), 0)
    UNION ALL SELECT 'INCIDENTES: titulo, cliente, prioridad, fecha de ingreso u OK cliente distintos', COUNT(*) FROM dbo.INCIDENTES o INNER JOIN dbo.CG_INCIDENTES c ON c.ID = o.ID WHERE ISNULL(o.TITULO, N'') <> ISNULL(c.TITULO, N'') OR ISNULL(o.ID_CLIENTE, -1) <> ISNULL(c.ID_CLIENTE, -1) OR ISNULL(o.PRIORIDAD, -1) <> ISNULL(c.PRIORIDAD, -1) OR ISNULL(o.FECHA_INGRESO, -1) <> ISNULL(c.FECHA_INGRESO, -1) OR ISNULL(o.OK_CLIENTE, N'') <> ISNULL(c.OK_CLIENTE, N'')
    UNION ALL SELECT 'INCIDENTES: CREACION vacia en CG_ pero con valor en el original', COUNT(*) FROM dbo.INCIDENTES o INNER JOIN dbo.CG_INCIDENTES c ON c.ID = o.ID WHERE NULLIF(LTRIM(RTRIM(o.CREACION)), '') IS NOT NULL AND LTRIM(RTRIM(o.CREACION)) <> '0' AND c.CREACION IS NULL
    UNION ALL SELECT 'PROYECTOS: titulo, descripcion, cliente, fechas u OK cliente distintos', COUNT(*) FROM dbo.PROYECTOS o INNER JOIN dbo.CG_PROYECTOS c ON c.ID = o.ID WHERE ISNULL(o.TITULO, N'') <> ISNULL(c.TITULO, N'') OR ISNULL(o.DESCRIPCION, N'') <> ISNULL(c.DESCRIPCION, N'') OR ISNULL(o.ID_CLIENTE, -1) <> ISNULL(c.ID_CLIENTE, -1) OR ISNULL(o.FECHA_INGRESO, -1) <> ISNULL(c.FECHA_INGRESO, -1) OR ISNULL(o.FECHA_ENTREGA, -1) <> ISNULL(c.FECHA_ENTREGA, -1) OR ISNULL(o.OK_CLIENTE, N'') <> ISNULL(c.OK_CLIENTE, N'')
    UNION ALL SELECT 'PROYECTOS: CREACION vacia en CG_ pero con valor en el original', COUNT(*) FROM dbo.PROYECTOS o INNER JOIN dbo.CG_PROYECTOS c ON c.ID = o.ID WHERE NULLIF(LTRIM(RTRIM(o.CREACION)), '') IS NOT NULL AND LTRIM(RTRIM(o.CREACION)) <> '0' AND c.CREACION IS NULL
    UNION ALL SELECT 'AVANCES: texto o fecha distintos del original', COUNT(*) FROM dbo.RELAINC o INNER JOIN dbo.CG_AVANCES c ON c.ID = o.ID WHERE ISNULL(o.DESCRIPCION, N'') <> CAST(ISNULL(c.DESCRIPCION, '') AS NVARCHAR(4000)) OR ISNULL(o.FECHA, -1) <> ISNULL(c.FECHA, -1) OR ISNULL(o.CODOBJETO, -1) <> ISNULL(c.CODOBJETO, -1)
    UNION ALL SELECT 'INCIDENTES o PROYECTOS con ESTADO vacio', (SELECT COUNT(*) FROM dbo.CG_INCIDENTES WHERE ESTADO IS NULL) + (SELECT COUNT(*) FROM dbo.CG_PROYECTOS WHERE ESTADO IS NULL)

    -- A8) Identidades: el proximo ID no debe ser menor que el maximo cargado
    UNION ALL SELECT 'Identidad desfasada (CG_INCIDENTES, CG_PROYECTOS, CG_AVANCES, CG_AGENDA, CG_APL, CG_CLIENTES)',
        (CASE WHEN IDENT_CURRENT('dbo.CG_INCIDENTES') < ISNULL((SELECT MAX(ID) FROM dbo.CG_INCIDENTES), 0) THEN 1 ELSE 0 END)
      + (CASE WHEN IDENT_CURRENT('dbo.CG_PROYECTOS') < ISNULL((SELECT MAX(ID) FROM dbo.CG_PROYECTOS), 0) THEN 1 ELSE 0 END)
      + (CASE WHEN IDENT_CURRENT('dbo.CG_AVANCES') < ISNULL((SELECT MAX(ID) FROM dbo.CG_AVANCES), 0) THEN 1 ELSE 0 END)
      + (CASE WHEN IDENT_CURRENT('dbo.CG_AGENDA') < ISNULL((SELECT MAX(ID) FROM dbo.CG_AGENDA), 0) THEN 1 ELSE 0 END)
      + (CASE WHEN IDENT_CURRENT('dbo.CG_APL') < ISNULL((SELECT MAX(ID) FROM dbo.CG_APL), 0) THEN 1 ELSE 0 END)
      + (CASE WHEN IDENT_CURRENT('dbo.CG_CLIENTES') < ISNULL((SELECT MAX(ID) FROM dbo.CG_CLIENTES), 0) THEN 1 ELSE 0 END)

    -- A9) Datos que la aplicacion necesita (inicio.asp busca los tipos de avance "Testing" y "Solicitud")
    UNION ALL SELECT 'Tipos de avance Testing / Solicitud que faltan en CG_TIPO_AVANCE', 2 - (SELECT COUNT(DISTINCT UPPER(LTRIM(RTRIM(DESCRIPCION)))) FROM dbo.CG_TIPO_AVANCE WHERE UPPER(LTRIM(RTRIM(DESCRIPCION))) IN ('TESTING', 'SOLICITUD'))
    UNION ALL SELECT 'CG_COR_RESPONSABLES sin ID_SEG', COUNT(*) FROM dbo.CG_COR_RESPONSABLES WHERE NULLIF(LTRIM(RTRIM(ID_SEG)), '') IS NULL
) x
ORDER BY CASE WHEN x.FILAS_CON_PROBLEMA = 0 THEN 1 ELSE 0 END, x.CONTROL;
GO

-- =====================================================================
-- B) DETALLE (para investigar los controles que dieron REVISAR)
-- =====================================================================

-- B1) Logins de responsables que no estan en vw_UserGrupos (personas dadas de baja en AD) y cuantos registros tiene cada uno
SELECT t.TABLA, t.LOGIN, COUNT(*) AS REGISTROS
FROM (
    SELECT 'CG_INCIDENTES (gestion)' AS TABLA, RESPON_GESTION_SEG AS LOGIN FROM dbo.CG_INCIDENTES WHERE RESPON_GESTION_SEG IS NOT NULL
    UNION ALL SELECT 'CG_INCIDENTES (tecnico)', RESPON_TEC_SEG FROM dbo.CG_INCIDENTES WHERE RESPON_TEC_SEG IS NOT NULL
    UNION ALL SELECT 'CG_PROYECTOS (gestion)', RESPON_GESTION_SEG FROM dbo.CG_PROYECTOS WHERE RESPON_GESTION_SEG IS NOT NULL
    UNION ALL SELECT 'CG_PROYECTOS (tecnico)', RESPON_TEC_SEG FROM dbo.CG_PROYECTOS WHERE RESPON_TEC_SEG IS NOT NULL
    UNION ALL SELECT 'CG_AGENDA', ID_RESPON_SEG FROM dbo.CG_AGENDA WHERE ID_RESPON_SEG IS NOT NULL
    UNION ALL SELECT 'CG_LICENCIAS', ID_RESPON_SEG FROM dbo.CG_LICENCIAS WHERE ID_RESPON_SEG IS NOT NULL
) t
WHERE NOT EXISTS (SELECT 1 FROM dbo.vw_UserGrupos u WHERE u.USRNET = t.LOGIN)
GROUP BY t.TABLA, t.LOGIN
ORDER BY t.LOGIN, t.TABLA;
GO

-- B2) Responsables cuyo id de origen no tiene equivalencia en CG_COR_RESPONSABLES (los que dieron "sin login")
SELECT 'INCIDENTES gestion' AS CAMPO, i.RESPON_GESTION AS ID_ORIGEN, COUNT(*) AS REGISTROS FROM dbo.CG_INCIDENTES i WHERE i.RESPON_GESTION IS NOT NULL AND i.RESPON_GESTION_SEG IS NULL GROUP BY i.RESPON_GESTION
UNION ALL SELECT 'INCIDENTES tecnico', i.RESPON_TEC, COUNT(*) FROM dbo.CG_INCIDENTES i WHERE ISNULL(i.RESPON_TEC, 0) <> 0 AND i.RESPON_TEC_SEG IS NULL GROUP BY i.RESPON_TEC
UNION ALL SELECT 'PROYECTOS gestion', p.RESPON_GESTION, COUNT(*) FROM dbo.CG_PROYECTOS p WHERE p.RESPON_GESTION IS NOT NULL AND p.RESPON_GESTION_SEG IS NULL GROUP BY p.RESPON_GESTION
UNION ALL SELECT 'PROYECTOS tecnico', p.RESPON_TEC, COUNT(*) FROM dbo.CG_PROYECTOS p WHERE ISNULL(p.RESPON_TEC, 0) <> 0 AND p.RESPON_TEC_SEG IS NULL GROUP BY p.RESPON_TEC
UNION ALL SELECT 'AGENDA', a.ID_RESPON, COUNT(*) FROM dbo.CG_AGENDA a WHERE a.ID_RESPON IS NOT NULL AND a.ID_RESPON_SEG IS NULL GROUP BY a.ID_RESPON
UNION ALL SELECT 'LICENCIAS', l.ID_RESPON, COUNT(*) FROM dbo.CG_LICENCIAS l WHERE l.ID_RESPON IS NOT NULL AND l.ID_RESPON_SEG IS NULL GROUP BY l.ID_RESPON
UNION ALL SELECT 'AVANCES (IDUSUARIO original)', TRY_CAST(o.IDUSUARIO AS INT), COUNT(*) FROM dbo.CG_AVANCES c INNER JOIN dbo.RELAINC o ON o.ID = c.ID WHERE c.IDUSUARIO_SEG IS NULL GROUP BY TRY_CAST(o.IDUSUARIO AS INT);
GO

-- B3) Referencias rotas (primeras 20 de cada tipo)
SELECT TOP 20 'INCIDENTE con proyecto inexistente' AS PROBLEMA, i.ID, i.ID_PROYECTO AS VALOR FROM dbo.CG_INCIDENTES i WHERE ISNULL(i.ID_PROYECTO, 0) <> 0 AND NOT EXISTS (SELECT 1 FROM dbo.CG_PROYECTOS p WHERE p.ID = i.ID_PROYECTO) ORDER BY i.ID;
SELECT TOP 20 'AVANCE huerfano' AS PROBLEMA, a.ID, a.CODOBJETO AS VALOR, a.TIPOOBJETO FROM dbo.CG_AVANCES a
WHERE (a.TIPOOBJETO = 'inc' AND NOT EXISTS (SELECT 1 FROM dbo.CG_INCIDENTES i WHERE i.ID = a.CODOBJETO)) OR (a.TIPOOBJETO = 'proy' AND NOT EXISTS (SELECT 1 FROM dbo.CG_PROYECTOS p WHERE p.ID = a.CODOBJETO)) ORDER BY a.ID;
GO

-- B4) ESTADO migrado: valor de VER (o ESTADO) en el original contra ESTADO en CG_ (debe coincidir; NULL -> 1)
-- Si el original ya tiene la columna ESTADO en lugar de VER, reemplazar VER por ESTADO en las dos consultas.
SELECT 'INCIDENTES' AS TABLA, o.VER AS VALOR_ORIGINAL, c.ESTADO AS ESTADO_EN_CG, COUNT(*) AS FILAS FROM dbo.INCIDENTES o INNER JOIN dbo.CG_INCIDENTES c ON c.ID = o.ID GROUP BY o.VER, c.ESTADO
UNION ALL SELECT 'PROYECTOS', o.VER, c.ESTADO, COUNT(*) FROM dbo.PROYECTOS o INNER JOIN dbo.CG_PROYECTOS c ON c.ID = o.ID GROUP BY o.VER, c.ESTADO
ORDER BY 1, 2;
GO

-- B5) Tipos de avance usados en el historial migrado (el TIPO historico se copio tal cual; solo tiene descripcion si coincide con CG_TIPO_AVANCE)
SELECT a.TIPO, t.DESCRIPCION AS DESCRIPCION_TIPO_AVANCE, COUNT(*) AS FILAS
FROM dbo.CG_AVANCES a LEFT JOIN dbo.CG_TIPO_AVANCE t ON CAST(t.ID AS NVARCHAR(50)) = LTRIM(RTRIM(a.TIPO))
GROUP BY a.TIPO, t.DESCRIPCION ORDER BY COUNT(*) DESC;
SELECT ID, DESCRIPCION, ESTADO FROM dbo.CG_TIPO_AVANCE ORDER BY ID;
GO

-- B6) RESPONSABLE actual de incidentes y proyectos (tomado del ultimo avance; si no habia, FUNCIONAL)
SELECT 'INCIDENTES' AS TABLA, RESPONSABLE, COUNT(*) AS FILAS FROM dbo.CG_INCIDENTES GROUP BY RESPONSABLE
UNION ALL SELECT 'PROYECTOS', RESPONSABLE, COUNT(*) FROM dbo.CG_PROYECTOS GROUP BY RESPONSABLE ORDER BY 1, 3 DESC;
GO

-- B7) Muestra lado a lado (10 incidentes): original contra CG_. La fecha de CREACION se reconstruye desde los dias guardados.
SELECT TOP 10 o.ID, o.TITULO AS TITULO_ORIGINAL, c.TITULO AS TITULO_CG,
       o.CREACION AS CREACION_ORIGINAL, c.CREACION AS DIAS_EN_CG, DATEADD(DAY, c.CREACION, '19000101') AS FECHA_RECONSTRUIDA,
       o.RESPON_GESTION AS GESTION_ID_ORIGEN, c.RESPON_GESTION_SEG AS GESTION_LOGIN, c.ESTADO
FROM dbo.INCIDENTES o INNER JOIN dbo.CG_INCIDENTES c ON c.ID = o.ID ORDER BY o.ID DESC;
GO

-- B8) El avance largo (el que no cabia en 4000 caracteres) debe estar completo
SELECT TOP 5 c.ID, LEN(c.AVANCES) AS LARGO_EN_CG, LEN(o.AVANCES) AS LARGO_ORIGINAL
FROM dbo.CG_INCIDENTES c INNER JOIN dbo.INCIDENTES o ON o.ID = c.ID ORDER BY LEN(o.AVANCES) DESC;
GO
